INSERT INTO feature VALUES('named-instances','effects','Named effect instances','effect-rows','implemented','uncommon','mainstream languages','A row names an instance of an interface by a label, `-> [a : I] B`, apart from the interface''s default and from every other instance, so one row holds two instances of one interface. A label of a definition''s result row binds a capability of the whole interface at a region binder of its own, after every parameter the definition writes; a call supplies it by name, `f[.a = c]`, or omits it and passes the one instance of the interface handled where the call stands, a capability scope''s or a label of the caller''s row, refused as unanswered where none stands and as ambiguous where several do. A label naming a region binder of the telescope, `[r : Region] (c : Cap[…] at r) -> [r : I] B`, is that binder''s instance, the spelling the printer writes. A label may name a theory''s instance, `-> [st : State.Eff with sort S = Integer] B`: its capability is over the theory''s operations at the sorts the entry fixes.','core-term core-checker core-incremental surface-grammar surface-lowering surface-pretty surface-format surface-diagnostics','corpus/model/control/named-instances.gandr corpus/pathological/control/named-instances.gandr corpus/ledger/syntax/f-type.row.labelled.gandr corpus/ledger/syntax/f-type.result.labelled.gandr corpus/ledger/diagnostics/InstanceAmbiguous.gandr corpus/ledger/diagnostics/InstanceUnanswered.gandr','corpus/model/control/named-instances.gandr',NULL);
